Debounce (TypeScript) — what it does
- Delays a function call until a pause in events. Useful to reduce expensive work (API requests, layout, logging) from high-frequency events (input, scroll, resize).

Code (typed, supports leading/trailing, cancel, flush)
- paste into your utils file.

```ts
type AnyFn = (...args: any[]) => any;
type Debounced<T extends AnyFn> = ((...args: Parameters<T>) => void) & {
  cancel: () => void;
  flush: () => void;
};

export function debounce<T extends AnyFn>(
  fn: T,
  wait = 200,
  { leading = false, trailing = true } = {}
): Debounced<T> {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<T> | null = null;
  let lastThis: any = null;
  let calledLeading = false;

  const invoke = () => {
    if (lastArgs) {
      fn.apply(lastThis, lastArgs);
      lastArgs = lastThis = null;
    }
    calledLeading = false;
  };

  function cancel() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    lastArgs = lastThis = null;
    calledLeading = false;
  }

  function flush() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
      invoke();
    }
  }

  function debounced(this: any, ...args: Parameters<T>) {
    lastArgs = args;
    lastThis = this;

    if (leading && !calledLeading) {
      calledLeading = true;
      fn.apply(lastThis, lastArgs);
      lastArgs = lastThis = null;
      // still allow a trailing call if configured
    }

    if (timer) clearTimeout(timer);
    if (trailing) timer = setTimeout(invoke, wait);
  }

  debounced.cancel = cancel;
  debounced.flush = flush;
  return debounced as Debounced<T>;
}
```

When to use / trade-offs
- Use: search-as-you-type, window resize, autosave — when you want the final settled event.
- Trade-offs: adds latency to the first/last action; may drop intermediate events (not suitable when every event matters).
- Alternative: throttle if you need regular execution at fixed intervals instead of after inactivity.

